import React, { useEffect, useState } from "react";
import MainNav from "../../MainNav/MainNav";
import ArtistManagerNav from "../ArtistManagerNav/ArtistManagerNav";
import "./Applications.css";
import axios from "axios";

const BASE_URL = "http://localhost:5000/applications";

function Applications() {
  const handleSignOut = () => {
    console.log("Sign out clicked");
  };

  const userName = "Manuth"; // mock user

  const [applications, setApplications] = useState([]);

  // Fetch pending applications
  const fetchApplications = async () => {
    try {
      const res = await axios.get(BASE_URL);
      setApplications(res.data.applications || []);
    } catch (err) {
      console.error("Error fetching applications:", err);
    }
  };

  useEffect(() => {
    fetchApplications();
  }, []);

  // Approve function
  const handleApprove = async (id) => {
    try {
      await axios.put(`${BASE_URL}/${id}/approve`);
      setApplications(applications.filter((app) => app._id !== id));
    } catch (err) {
      console.error("Error approving application:", err);
    }
  };

  // Reject function
  const handleReject = async (id) => {
    try {
      await axios.delete(`${BASE_URL}/${id}/reject`);
      setApplications(applications.filter((app) => app._id !== id));
    } catch (err) {
      console.error("Error rejecting application:", err);
    }
  };

  return (
    <div className="dashboard-page">
      <MainNav />

      {/* Dashboard Header */}
      <header className="dashboard-header">
        <div className="dashboard-header-container">
          <div className="dashboard-header-left">
            <h1 className="dashboard-header-title">Artist Manager Dashboard</h1>
            <p className="dashboard-welcome-message">
              Welcome back, {userName}! Manage your artists and applications efficiently.
            </p>
          </div>
          <button className="dashboard-signout-btn" onClick={handleSignOut}>
            <svg
              className="signout-icon"
              width="18"
              height="18"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"></path>
              <polyline points="16,17 21,12 16,7"></polyline>
              <line x1="21" y1="12" x2="9" y2="12"></line>
            </svg>
            <span>Sign Out</span>
          </button>
        </div>
      </header>

      <ArtistManagerNav />

      <h1>Pending Applications</h1>

      <div className="applications-list">
        {applications.length > 0 ? (
          applications.map((application) => (
            <ApplicationCard
              key={application._id}
              application={application}
              onApprove={handleApprove}
              onReject={handleReject}
            />
          ))
        ) : (
          <p>No pending applications.</p>
        )}
      </div>
    </div>
  );
}

// Single Application Card Component
function ApplicationCard({ application, onApprove, onReject }) {
  return (
    <div className="application-card">
      <h3>{application.stageName}</h3>
      <p>
        <strong>Name:</strong> {application.firstName} {application.lastName}
      </p>
      <p>
        <strong>Email:</strong> {application.email}
      </p>
      <p>
        <strong>Bio:</strong> {application.bio}
      </p>

      <div className="application-actions">
        <button
          className="approve-btn"
          onClick={() => onApprove(application._id)}
        >
          Approve
        </button>
        <button
          className="reject-btn"
          onClick={() => onReject(application._id)}
        >
          Reject
        </button>
      </div>
    </div>
  );
}

export default Applications;
